package com.example.simpleaccountant.ui.transactions;
import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.model.Transaction;import com.example.simpleaccountant.util.MoneyUtils;import java.util.*;
public class TransactionAdapter extends RecyclerView.Adapter<TransactionAdapter.VH>{public interface Listener{void onDelete(Transaction t);}private List<Transaction> items=new ArrayList<>();private final Listener listener;public TransactionAdapter(Listener l){listener=l;}public void setItems(List<Transaction> d){items=d;notifyDataSetChanged();}
@NonNull @Override public VH onCreateViewHolder(@NonNull ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_simple,p,false));}
@Override public void onBindViewHolder(@NonNull VH h,int i){Transaction t=items.get(i);h.t1.setText(t.getTitle()+" ("+t.getType()+")");h.t2.setText(MoneyUtils.format(t.getAmount())+" | "+t.getTransactionDate());h.del.setOnClickListener(v->listener.onDelete(t));}
@Override public int getItemCount(){return items.size();}static class VH extends RecyclerView.ViewHolder{TextView t1,t2;ImageButton del;VH(View v){super(v);t1=v.findViewById(R.id.t1);t2=v.findViewById(R.id.t2);del=v.findViewById(R.id.btnDelete);}}}
